raw:
{
  "scores": {
    "脑洞鲜": {
      "score": 8,
      "failures": [
        "“一寸黄纸，一滴朱砂，一缕残魂。”——召魂用纸札的做法与常见的‘符箓驱鬼’套路相同，新异度有限。",
        "“魂灯只剩两日半，得靠军功点把灯芯添回去。”——‘数字化军功换命’很像常见功德值/积分仓库的变形，没有脱离计点型系统思路。"
      ],
      "success": "“替你修指……我可补魂。”——用纸札给活人‘补魂指’，把驱鬼术延伸到肉身修补，在同类题材里较少见。",
      "suggestion": "继续把‘纸札可修补人体损坏’做深，设计不同部位对应不同代价，避免只停留在‘召魂+换军功’的浅层。"
    },
    "撞题度": {
      "score": 8,
      "failures": [
        "“阴兵——是阴兵——”——阴兵冲阵的视觉与现有‘请阴兵打脸’作品相近。",
        "“十点军功，差一命”——‘集齐若干点数救亲人’与常见《功德商城》《功德点换命》路径相似。"
      ],
      "success": "女主与副都督达成‘补魂指⇄军功’的利益置换，把灵异救父与军旅权谋进行了新组合。",
      "suggestion": "在后续情节里强化‘补魂手指’所带来的战术优势或政治连锁，而不只是一次交易，进一步降低与同类作品交集。"
    },
    "长线性": {
      "score": 7,
      "failures": [
        "“魂灯只剩两日半”——极短时限虽然紧张，但若父亲复活后情节方向未示，后续动力可能失速。",
        "军功获取目前只列出斩首/破营三档，没有展示随剧情升级或衍生代价，可持续性仍显模糊。"
      ],
      "success": "每一点军功都需要战场兑现、女主折寿或放魂札，存在递进难度与成本，为连载留出空间。",
      "suggestion": "提早埋下父亲复活后的‘更大债务’或‘魂裂后遗症’，让目标链从10点延伸出第二、第三阶段。"
    },
    "开篇钩": {
      "score": 9,
      "failures": [
        "“车里闷得发霉”——形容词堆积稍显平常，浪费首段注意力。",
        "“押解官兵不过二十来人”——信息量正确，但属于常规统计，冲击力有限。"
      ],
      "success": "“纸札哗地燃起…灰影落地，化成…战死名录上的‘通敌叛将’。”——千字内即亮出召魂、父亲冤死与山匪危机，强钩且信息密度高。",
      "suggestion": "删减首段静态环境描写，把‘囚车失控’提前两句，让动态冲击更早进入读者视野。"
    },
    "脑洞值": {
      "score": 8,
      "failures": [
        "“纸札在，你就能像健指；纸札烧，你疼得比断指时更甚。”——痛感惩罚仍是老套的‘失效反噬’逻辑。",
        "“以血替香”——血祭元素常见，缺乏新的施法材料或场景。"
      ],
      "success": "灵异道术与军功体系绑定，开辟了‘兵符／阴兵—军功—官场’的闭环，操作空间大。",
      "suggestion": "为每类纸札设计独特副作用（失温、幻听、梦魇等），并让这些副作用在剧情中不断升级。"
    },
    "爽节奏": {
      "score": 8,
      "failures": [
        "第二章大量内部景观描写，如“堡中巷道狭窄，戍楼紧凑得像一层层骨节”，连续三段无冲突，拉低推进速度。",
        "第三章‘净血净墨’仪式细节占比过大，动作描写多而打脸节点稍后置。"
      ],
      "success": "每章都保证至少一次极限脱困或利益交换（山匪屠杀、进堡谈判、补魂指），读者很快获得回报。",
      "suggestion": "控制单次仪式/环境渲染在80字内，2-3段内就插入新的冲突或对话反击。"
    },
    "人设彩": {
      "score": 8,
      "failures": [
        "女主内心独白多以任务倒计时为主，情感层次（对父亲歉疚以外）暂时单一。",
        "男主裴屿生的‘倦意+残指’形象鲜明，但动机仅用一句“杀心最盛”带过，深度不足。"
      ],
      "success": "姜聆雪在‘折寿七年也要救父’与‘必须亲手取最后一点军功’中展现了决绝与控制欲，反差强。",
      "suggestion": "增加男女主的非任务向私欲（她想要的未来身份，他隐藏的恐惧），以行为而非旁白展现。"
    },
    "对话味": {
      "score": 7,
      "failures": [
        "“姑娘好算计”——‘算计’属于现代口吻，高频出现易跳戏。",
        "“不能示弱。”——纯现代心理旁白，突兀地打断古风氛围。"
      ],
      "success": "裴屿生一句“我随你赌”既合身份又暗含挑衅，角色辨识度高。",
      "suggestion": "保留利落现代节奏，但每20行对话至少插一句符合军旅身份的敬称或兵家隐喻，维稳时代感。"
    },
    "画面感": {
      "score": 9,
      "failures": [
        "“烤得发硬”——形容鞋底的比喻略口语，与整体血雪意境不匹配。",
        "“像有人蒙了天地一层棉纱”——意象漂亮，但与战场紧张度略冲突。"
      ],
      "success": "“陌刀腾空…刀面反光，扫落三名匪徒的喉咙，腥味炸开，篝火被溅得滋滋作响。”动线、声色、嗅觉齐备，画面立体。",
      "suggestion": "偶尔的现代化口语替换为更有色温的意向词，如“烤得硬脆”→“焦硬如铁”。"
    },
    "古韵感": {
      "score": 7,
      "failures": [
        "“刻度条：阳寿折耗Ⅰ/Ⅴ”——UI化提示完全现代，破古韵。",
        "“系统型计分词‘点功’、‘够点’高频出现，略显游戏腔。” 
      ],
      "success": "大量兵甲、行军、官职用语（百户、校尉、虎翎军）准确，稳住整体时代框架。",
      "suggestion": "把UI文字改为旁白或沙漏意向，如“寿数已蚀其一”替代刻度条，降低界面感。"
    },
    "悬念链": {
      "score": 8,
      "failures": [
        "父亲被夺功的真相仅一句台词抛出，后续追查线暂未延伸，悬念深度不足。",
        "敌军突然撤退的伏笔提到即断，缺少下一步暗示。"
      ],
      "success": "‘两日半阳寿+十点军功’形成明确倒计时，天然催生连环问题。",
      "suggestion": "在每章末尾用一句对话或物件暗示下一谜团，如‘赫连冽的亲兵名册上，空缺了一列’。"
    },
    "逻辑严": {
      "score": 7,
      "failures": [
        "同章内‘魂指三日时限’与‘若纸札烧就更疼’的约束口径不一致，惩罚强度模糊。",
        "押解官兵面对阴兵时既想斩首又乖乖放人，心理与军纪摇摆过速，可信度欠缺。"
      ],
      "success": "召魂→折寿→军功置换的因果链完整，代价写实，让超自然合理化。",
      "suggestion": "把魂札规则固定成文：生效时长、折寿比例、不可同时多札——并在角色对白里反复确认。"
    },
    "反转劲": {
      "score": 7,
      "failures": [
        "山匪瞬间被阴兵清场，胜负落差大但过程线性，缺少‘以为成功→再度翻车’的起伏。",
        "裴屿生几乎无犹豫就答应交易，冲突解决过顺滑，反转张力减弱。"
      ],
      "success": "用补魂指把敌我关系转成利益共同体，轻巧制造角色立场翻转。",
      "suggestion": "在关键选择前添一层误导信息，让读者先以为交易失败，再以角色暗线反杀制造波峰。"
    }
  },
  "weighted_total": 7.8,
  "strengths": [
    "开篇即用“纸札燃魂、父亲归魄”打造强视觉和情感冲击，信息密度媲美高分范例（“纸札哗地燃起…灰影落地”）。",
    "角色利益交错清晰：女主急救父、男主补指，两条需求互卡，富有戏剧张力（“我以纸札，换。”）。"
  ],
  "top_issues": [
    {
      "problem": "现代界面感与古风基调冲撞，影响代入。",
      "prompt_fix": "在系统提示中加入：‘禁止出现UI式数值描述，倒计时请以意象或旁白表述’。",
      "rewrite_example": "原：『刻度条：阳寿折耗Ⅰ/Ⅴ』\n改：『她心头的寿烛又短了一茎，五分之剩其四，火苗低得几不可见。』"
    },
    {
      "problem": "部分冲突解决过快，反转深度不足。",
      "prompt_fix": "系统提示：‘关键博弈需经历“以为成→险被破→绝地翻盘”三段式，再进入下一个爽点’。",
      "rewrite_example": "山匪见阴兵逃散→押解官兵趁乱要处决女主→赫连冽私兵突然出现截走魂灯→女主以魂札胁迫赫连冽，重新夺回主导。"
    },
    {
      "problem": "长线目标只有十点军功，后续动力可能不足。",
      "prompt_fix": "指令：‘在前10万字内递增目标代价，例如父魂复生引发更大诅咒、需要百点功勋抵消，否则魂灯反噬全军’。",
      "rewrite_example": "父亲复活后，灯火却变成墨色妖焰，裴屿生发现自身魂指也被牵连——女主不得不向朝廷讨要“百战龙章”以镇灯，再度踏上杀敌夺功之路。"
    }
  ]
}
